#include <RH_ASK.h>
#include <SPI.h> // required by RadioHead even though this project doesn't use SPI directly

// RF433 Remote — Transmitter
// Reads the joystick and continuously broadcasts a direction command.

RH_ASK driver; // defaults to DATA on pin 12

const int VRX_PIN = A0;
const int VRY_PIN = A1;

void setup() {
  driver.init();
}

void loop() {
  char command = commandFromJoystick();
  driver.send((uint8_t *)&command, 1);
  driver.waitPacketSent();
  delay(100); // send ~10 times per second
}

char commandFromJoystick() {
  int x = analogRead(VRX_PIN);
  int y = analogRead(VRY_PIN);

  if (y > 700) return 'F';
  if (y < 300) return 'B';
  if (x > 700) return 'R';
  if (x < 300) return 'L';
  return 'S'; // centered = stop
}

#include <RH_ASK.h>
#include <SPI.h>

// RF433 Remote — Car Receiver
// Drives the motors according to the last valid command received.

RH_ASK driver;

const int IN1 = 2, IN2 = 3;
const int IN3 = 4, IN4 = 5;
const int ENA = 6, ENB = 9;
const int SPEED = 180;

const unsigned long COMMAND_TIMEOUT_MS = 500; // stop if no command arrives for this long
unsigned long lastCommandAt = 0;

void setup() {
  driver.init();

  pinMode(IN1, OUTPUT); pinMode(IN2, OUTPUT);
  pinMode(IN3, OUTPUT); pinMode(IN4, OUTPUT);
  pinMode(ENA, OUTPUT); pinMode(ENB, OUTPUT);
}

void loop() {
  uint8_t buffer[1];
  uint8_t bufferLength = sizeof(buffer);

  if (driver.recv(buffer, &bufferLength)) {
    lastCommandAt = millis();
    applyCommand((char)buffer[0]);
  }

  // Safety: if the remote goes out of range or is turned off, stop driving
  // rather than continuing the last command forever.
  if (millis() - lastCommandAt > COMMAND_TIMEOUT_MS) {
    stopMotors();
  }
}

void applyCommand(char command) {
  switch (command) {
    case 'F': driveForward(); break;
    case 'B': driveBackward(); break;
    case 'L': pivotLeft();    break;
    case 'R': pivotRight();   break;
    case 'S': stopMotors();   break;
  }
}

void driveForward() {
  digitalWrite(IN1, HIGH); digitalWrite(IN2, LOW);
  digitalWrite(IN3, HIGH); digitalWrite(IN4, LOW);
  analogWrite(ENA, SPEED); analogWrite(ENB, SPEED);
}

void driveBackward() {
  digitalWrite(IN1, LOW); digitalWrite(IN2, HIGH);
  digitalWrite(IN3, LOW); digitalWrite(IN4, HIGH);
  analogWrite(ENA, SPEED); analogWrite(ENB, SPEED);
}

void pivotLeft() {
  digitalWrite(IN1, LOW); digitalWrite(IN2, HIGH);
  digitalWrite(IN3, HIGH); digitalWrite(IN4, LOW);
  analogWrite(ENA, SPEED); analogWrite(ENB, SPEED);
}

void pivotRight() {
  digitalWrite(IN1, HIGH); digitalWrite(IN2, LOW);
  digitalWrite(IN3, LOW); digitalWrite(IN4, HIGH);
  analogWrite(ENA, SPEED); analogWrite(ENB, SPEED);
}

void stopMotors() {
  analogWrite(ENA, 0);
  analogWrite(ENB, 0);
}
